  def event_boundary_facts_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var event_boundary_facts: Factory_Material_Continuity_Coordinator.EventBoundaryFacts = $

  def put_event_boundary_facts(value : Factory_Material_Continuity_Coordinator.EventBoundaryFacts) : Unit = {
    Contract(
      Modifies(event_boundary_facts),
      Ensures(
        event_boundary_facts == value
      )
    )
    Spec {
      event_boundary_facts = value
    }

    Art.putValue(event_boundary_facts_Id, Factory_Material_Continuity_Coordinator.EventBoundaryFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class EventAcquisition_Initialization_Api (
  val id: Art.BridgeId,
  val material_event_Id : Art.PortId,
  val event_boundary_facts_Id : Art.PortId) extends EventAcquisition_Api

@datatype class EventAcquisition_Operational_Api (
