  val event_boundary_facts_Id : Art.PortId) extends EventAcquisition_Api {

  // Logika spec var representing port state for incoming data port
  @spec var material_event: Factory_Material_Continuity_Coordinator.MaterialEvent.Type = $

  def get_material_event() : Option[Factory_Material_Continuity_Coordinator.MaterialEvent.Type] = {
    Contract(
      Ensures(
        Res == Some(material_event)
      )
    )
    val value : Option[Factory_Material_Continuity_Coordinator.MaterialEvent.Type] = Art.getValue(material_event_Id) match {
      case Some(Factory_Material_Continuity_Coordinator.MaterialEvent_Payload(v)) => Some(v)
